command:
dev-browser --headless --browser cairn-ui-check <<'EOF'
const page = await browser.getPage('ui-check');
const flares = await page.evaluate(() => {
  const out = [];
  for (const p of window.__cairnUi.points.values()) {
    if (p.kind === 'flare') out.push({ id: p.id, text: p.text, question: p.question, answerLine: p.answerLine, resolved: p.resolved });
  }
  return out;
});
console.log('FLARES:', JSON.stringify(flares, null, 2));
EOF

